   const page=current.pages.find(v=>v.id===params.get('page'))||current.pages.find(v=>v.id===current.lastPage)||current.pages[0];if(!page){go(15);return true;}const view=B.pageView(page,current);if(n===20){reading(ctx,current,n);return true;}back(16);bind('.back',()=>UI.back('m08-p'+(n===19?'18':'16')+'.html?id='+id+'&page='+encodeURIComponent(page.id)));bind('.toc',()=>go(15));
   if(n===17){text('.page-label','第 '+(current.pages.indexOf(page)+1)+' 页');text('.story-title',view.title);text('.story-copy',view.blocked?'关联内容已不可见':view.body);const actions=all('.tools button');for(const [i,b]of actions.entries()){b.removeAttribute('onclick');b.onclick=i===0?()=>go(15):i===1?async()=>{const bookmarks=book().bookmarks||[],pages=book().pages.filter(v=>bookmarks.includes(v.id));const selected=await UI.sheet({title:'我的书签',message:pages.length?'选择一页继续阅读。':'还没有书签，可在阅读页面点击书签。',actions:pages.map(v=>({label:B.pageView(v,book()).title,value:v.id}))});if(selected)go(16,{page:selected});}:i===2?()=>go(18,{page:page.id}):i===3?()=>go(13):()=>go(21);}actions[2].disabled=view.blocked||!PrototypePreferences.privacy().replies;const more=actions[4];more.textContent='管理这本书 · 书名、归档、导出与删除';return true;}
